import{_ as a,o as t,c as l,a2 as r}from"./chunks/framework.Bx7X8BVG.js";const f=JSON.parse('{"title":"选择版本与快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1790778157000}'),d={name:"guide/index.md"};function n(o,e,i,u,c,h){return t(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="选择版本与快速开始" tabindex="-1">选择版本与快速开始 <a class="header-anchor" href="#选择版本与快速开始" aria-label="Permalink to &quot;选择版本与快速开始&quot;">​</a></h1><p>当前正式发行版 <strong>v1.8.1</strong>。安装包、源码及测试范围以 <a href="https://github.com/lieren2012/cloudflare-tunnel-manager/releases/tag/v1.8.1" target="_blank" rel="noreferrer">Release</a> 和 <a href="/cloudflare-tunnel-manager/guide/verification">实际验证记录</a> 为准。</p><h2 id="选哪个版本" tabindex="-1">选哪个版本 <a class="header-anchor" href="#选哪个版本" aria-label="Permalink to &quot;选哪个版本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条件</th><th>建议</th></tr></thead><tbody><tr><td>NAS / Linux 服务器需要长期在线</td><td>Docker 版</td></tr><tr><td>Windows x64 本地电脑</td><td>Windows EXE；也提供 MSI</td></tr><tr><td>macOS M 系列芯片</td><td>Apple Silicon DMG</td></tr><tr><td>Debian/Ubuntu amd64 桌面</td><td>Linux DEB</td></tr><tr><td>Intel Mac / ARM Linux 桌面</td><td>当前无对应桌面包；不要下载不匹配的架构</td></tr></tbody></table><p>Docker 与桌面版共用管理功能，但运行环境、端口、数据目录、升级方式不同。电脑休眠、断网或服务停止会影响隧道访问；需要持续在线优先用服务器或 NAS。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ul><li><a href="/cloudflare-tunnel-manager/guide/docker">Docker 安装与卸载</a>：需要 Docker、Compose、Git，默认端口 19090。</li><li><a href="/cloudflare-tunnel-manager/guide/desktop">桌面端安装与升级</a>：内置 Node 与 cloudflared，本地端口自动分配。</li></ul><h2 id="首次注册与已有账号" tabindex="-1">首次注册与已有账号 <a class="header-anchor" href="#首次注册与已有账号" aria-label="Permalink to &quot;首次注册与已有账号&quot;">​</a></h2><p>新数据目录首次打开显示“创建管理员账户”，第一个账户成为管理员。已有数据则显示登录。后续注册用户需管理员审核。</p><p>面板账户是本次安装自己的账号，<strong>不是 Cloudflare 账号</strong>。Docker 服务器和本地桌面端各有数据目录，账号不会自动同步。升级后突然要求注册，先检查目录/挂载，不要直接创建新管理员覆盖排查线索。</p><h2 id="配置-cloudflare" tabindex="-1">配置 Cloudflare <a class="header-anchor" href="#配置-cloudflare" aria-label="Permalink to &quot;配置 Cloudflare&quot;">​</a></h2><p>需要可用于发布域名的 Cloudflare 账户、域名、Account ID 和 API Token。<a href="/cloudflare-tunnel-manager/get-credentials">按凭据教程创建令牌</a>，在“系统配置”里测试通过后保存。域名购买费用与 Tunnel 是否免费是两回事。</p><h2 id="创建第一条隧道" tabindex="-1">创建第一条隧道 <a class="header-anchor" href="#创建第一条隧道" aria-label="Permalink to &quot;创建第一条隧道&quot;">​</a></h2><ol><li>先确认业务服务已启动，可以直接访问，如 <code>http://127.0.0.1:8080</code> 或 <code>http://192.168.1.10:5000</code>。</li><li>打开“Tunnel 列表”，新建隧道，例如 <code>nas</code>。</li><li>点击“连接”，查看日志是否出现 <code>Registered tunnel connection</code>。</li><li>添加路由：<code>nas.example.com</code> → 业务服务地址。面板会创建对应 DNS CNAME。</li><li>从外部网络访问 <code>https://nas.example.com</code>，验证页面、登录和实际请求均可用。只有进程在运行不足以证明转发成功。</li></ol><p>“自启”表示面板服务启动后自动连接已配置隧道，<strong>不代表桌面程序已实现随操作系统开机启动</strong>。</p><h2 id="常用教程" tabindex="-1">常用教程 <a class="header-anchor" href="#常用教程" aria-label="Permalink to &quot;常用教程&quot;">​</a></h2><ul><li><a href="/cloudflare-tunnel-manager/guide/panel">管理面板</a></li><li><a href="/cloudflare-tunnel-manager/guide/update">Docker/桌面不同的更新方式</a></li><li><a href="/cloudflare-tunnel-manager/guide/api">外部 API 与 MCP：端口区别</a></li><li><a href="/cloudflare-tunnel-manager/guide/limits">免费版限制与用途</a></li><li><a href="/cloudflare-tunnel-manager/guide/security">安全、备份与公网访问</a></li><li><a href="/cloudflare-tunnel-manager/guide/faq">排错</a></li></ul>',17)])])}const p=a(d,[["render",n]]);export{f as __pageData,p as default};
